 ***********************************************************************************************
 */

use Admidio\Infrastructure\Plugins\Plugin;
use Admidio\Infrastructure\Plugins\PluginRegistry;
use Admidio\Infrastructure\Plugins\PluginWidget;
use Admidio\Infrastructure\Utils\SecurityUtils;
use Admidio\UI\Presenter\FormPresenter;
use Admidio\UI\Presenter\PagePresenter;

/*
 * This file is included by the plugin loader and is never an entry point of its own. Without the
 * Admidio bootstrap it could do nothing anyway; the guard only turns a PHP error into a message.
 */
if (realpath($_SERVER['SCRIPT_FILENAME'] ?? '') === __FILE__) {
    exit('This page may not be called directly!');
}

/**
 * The settings of the plugin.
 *
 * The role list holds the IDs of the roles the search is restricted to. An empty list means every
 * member is searched and no restriction has to be added to the search query.
 * @param Plugin $plugin
 * @return array<string,mixed>
 * @throws \Admidio\Infrastructure\Exception
 */
function searchMemberGetConfig(Plugin $plugin): array
{
    return $plugin->getSettingValues();
}

/**
 * Build the search form.
 * @param PagePresenter $formPage
 * @param array<string,mixed> $config
 * @param string $searchTerm
 * @return FormPresenter
 */
function searchMemberCreateForm(PagePresenter $formPage, array $config, string $searchTerm): FormPresenter
{
    global $gL10n;

    $placeholder = $config['search_member_search_city']
        ? $gL10n->get('PLG_SEARCH_PLACEHOLDER_INCLUDING_CITY')
        : $gL10n->get('PLG_SEARCH_PLACEHOLDER');

    $form = new FormPresenter(
        'adm_plugin_search_member',
        'plugin.search-member-form.logged-in.tpl',
        ADMIDIO_URL . FOLDER_MODULES . '/overview.php',
        $formPage,
        array('type' => 'vertical', 'method' => 'get', 'setFocus' => false, 'showRequiredFields' => false)
    );

    $form->addInput(
        'plg_search_usr',
        '',
        $searchTerm,
        array('type' => 'search', 'placeholder' => $placeholder)
    );
    $form->addSubmitButton('plg_btn_search', $gL10n->get('PLG_SEARCH'), array('icon' => 'bi-search'));

    return $form;
}

/**
 * Search the members of the organization by name, and optionally by city.
 * @param array<string,mixed> $config
 * @param string $searchTerm
 * @return array<int,array<string,string>>
 * @throws \Admidio\Infrastructure\Exception
 */
function searchMemberSearch(array $config, string $searchTerm): array
{
    global $gDb, $gL10n, $gProfileFields, $gCurrentOrgId;

    if (!empty($config['search_member_roles_sql'])) {
        $sqlRol = 'IN (' . implode(',', array_map('intval', $config['search_member_roles_sql'])) . ')';
    } else {
        $sqlRol = 'IS NOT NULL';
    }

    $searchString = '%' . $searchTerm . '%';

    $sql = 'SELECT
                usr_uuid,
                usr_login_name,
                first_name,
                last_name,
                city
            FROM
                (SELECT
                    DISTINCT usr_id,
                        usr_uuid,
                        usr_login_name,
                        last_name.usd_value AS last_name,
                        first_name.usd_value AS first_name,
                        city.usd_value AS city
                    FROM
                        ' . TBL_USERS . ' AS users
                    LEFT JOIN ' . TBL_USER_DATA . ' AS last_name
                            ON last_name.usd_usr_id = usr_id
                        AND last_name.usd_usf_id = ? -- $gProfileFields->getProperty(\'LAST_NAME\', \'usf_id\')
                    LEFT JOIN ' . TBL_USER_DATA . ' AS first_name
                            ON first_name.usd_usr_id = usr_id
                        AND first_name.usd_usf_id = ? -- $gProfileFields->getProperty(\'FIRST_NAME\', \'usf_id\')
                    LEFT JOIN ' . TBL_USER_DATA . ' AS city
                            ON city.usd_usr_id = usr_id
                        AND city.usd_usf_id = ? -- $gProfileFields->getProperty(\'CITY\', \'usf_id\')
                    LEFT JOIN ' . TBL_MEMBERS . '
                            ON mem_usr_id = usr_id
                        AND mem_begin <= ? -- DATE_NOW
                        AND mem_end    > ? -- DATE_NOW
                    INNER JOIN ' . TBL_ROLES . '
                            ON mem_rol_id = rol_id
                        AND rol_valid  = true
                    INNER JOIN ' . TBL_CATEGORIES . '
                            ON rol_cat_id = cat_id
                        AND cat_org_id = ? -- $gCurrentOrgId
                    WHERE usr_valid = true
                        AND mem_rol_id ' . $sqlRol . '
                ) AS data
            WHERE
                CONCAT(first_name, \' \', last_name) LIKE ?';

    $queryParams = array(
        $gProfileFields->getProperty('LAST_NAME', 'usf_id'),
        $gProfileFields->getProperty('FIRST_NAME', 'usf_id'),
        $gProfileFields->getProperty('CITY', 'usf_id'),
        DATE_NOW,
        DATE_NOW,
        $gCurrentOrgId,
        $searchString
    );

    if ($config['search_member_search_city']) {
        $sql .= ' OR city LIKE ?';
        $queryParams[] = $searchString;
    }

    $searchUserStatement = $gDb->queryPrepared($sql, $queryParams);

    $results = array();

    while ($row = $searchUserStatement->fetch()) {
        switch ((int)$config['search_member_show_names']) {
            case 2: // last name, first name
                $displayName = $row['last_name'] . ', ' . $row['first_name'];
                break;
            case 3: // first name
                $displayName = $row['first_name'];
                break;
            case 4: // login name
                $displayName = $row['usr_login_name'];
                break;
            default: // first name, last name
                $displayName = $row['first_name'] . ' ' . $row['last_name'];
        }

        $resultText = '<strong><a href="' . SecurityUtils::encodeUrl(
            ADMIDIO_URL . FOLDER_MODULES . '/profile/profile.php',
            array('user_uuid' => $row['usr_uuid'])
        ) . '" title="' . $gL10n->get('SYS_SHOW_PROFILE') . '">' . $displayName . '</a></strong>';

        if ($config['search_member_search_city'] && (string)$row['city'] !== '') {
            $resultText .= ' (' . $row['city'] . ')';
        }

        $results[] = array('resultText' => $resultText);
    }

    return $results;
}

/**
 * Build the widget of the overview page. Whether it is shown at all was decided before this is
 * called, by the preference **search_member_plugin_enabled**.
 * @param PagePresenter $page
 * @param Plugin $plugin
 * @return string
 * @throws \Admidio\Infrastructure\Exception|\Smarty\Exception
 */
function searchMemberRenderWidget(PagePresenter $page, Plugin $plugin): string
{
    global $gValidLogin, $gCurrentSession;

    if (!$gValidLogin) {
        return $plugin->renderTemplate($page, 'plugin.search-member-form.logged-out.tpl', array(
            'name' => $plugin->id
        ));
    }

    $config = searchMemberGetConfig($plugin);
    $searchTerm = admFuncVariableIsValid($_GET, 'plg_search_usr', 'string');

    $form = searchMemberCreateForm($page, $config, $searchTerm);
    $form->addToSmarty($page->getSmartyTemplate());
    $gCurrentSession->addFormObject($form);

    $variables = array(
        'name' => $plugin->id,
        'searchTerm' => $searchTerm,
        'results' => array()
    );

    if ($searchTerm !== '') {
        $variables['results'] = searchMemberSearch($config, $searchTerm);
    }

    return $plugin->renderTemplate($page, 'plugin.search-member-form.logged-in.tpl', $variables);
}

$searchMemberPlugin = PluginRegistry::get('search_member');
if ($searchMemberPlugin !== null) {
    PluginWidget::register($searchMemberPlugin, 'searchMemberRenderWidget', array(
        'sequence' => 3
    ));
}
